1521|  if( participants[0] == Caml_state ) {
1522|    pool* cur_pool;
1523|    pool* next_pool;
1524|
1525|    caml_plat_lock_blocking(&pool_freelist.lock);
1526|    cur_pool = pool_freelist.free;
1527|
1528|    while( cur_pool ) {
1529|      next_pool = cur_pool->next;
