1531|      caml_mem_unmap(cur_pool, Bsize_wsize(POOL_WSIZE));
1532|      cur_pool = next_pool;
1533|    }
1534|
1535|    pool_freelist.free = NULL;
1536|
1537|    caml_plat_unlock(&pool_freelist.lock);
